import importlib,importlib.machinery,importlib.metadata,importlib.util,json,os,socket,sys,types
from pathlib import Path
root=Path('/private/tmp/iter65-full-retry.Dz1JCbxd'); base=Path('/private/tmp/iter65-full-retry.Dz1JCbxd/baseline-test'); site=Path('/private/tmp/iter65-full-retry.Dz1JCbxd/baseline-site'); tests=base/'tests'
stream=Path('/private/tmp/iter65-full-retry.Dz1JCbxd/baseline.events.jsonl').open('x',encoding='utf-8',buffering=1)
def emit(kind,**kw): stream.write(json.dumps({'kind':kind,**kw},ensure_ascii=False)+'\n')
blocked={'socket.bind','socket.connect','socket.getaddrinfo','socket.gethostbyname','socket.gethostbyaddr','socket.getnameinfo','os.kill','os.killpg'}
mode='bootstrap'; bootstrap_count=0
spec=importlib.util.find_spec('urllib3'); expected=Path(next(iter(spec.submodule_search_locations)),'util','connection.py').resolve()
class GuardStop(BaseException): pass
def audit(event,args):
 global bootstrap_count
 if event not in blocked: return
 frame=sys._getframe(1); code=frame.f_code
 if mode=='bootstrap' and event=='socket.bind' and Path(code.co_filename).resolve()==expected and code.co_name=='_has_ipv6' and bootstrap_count==0:
  bootstrap_count+=1; emit('bootstrap_blocked',event=event,module='urllib3.util.connection',function='_has_ipv6',line=frame.f_lineno); raise PermissionError('offline startup probe denied')
 frames=[]
 while frame and len(frames)<10:
  c=frame.f_code; frames.append({'basename':os.path.basename(c.co_filename),'function':c.co_name,'line':frame.f_lineno}); frame=frame.f_back
 emit('unexpected_guard',event=event,mode=mode,frames=frames); raise GuardStop('unexpected network or signal operation')
sys.addaudithook(audit)
try:
 import urllib3
 from urllib3.util.connection import HAS_IPV6
 assert bootstrap_count==1 and HAS_IPV6 is False
 emit('bootstrap_complete',blocked_count=bootstrap_count,ipv6_available=HAS_IPV6,urllib3=urllib3.__version__)
 mode='run'
 sys.path[:0]=[str(base/'src'),str(site),str(base),str(tests)]
 import bt_api_base,pytest
 origin=Path(bt_api_base.__file__).resolve(); dist=importlib.metadata.distribution('bt_api_base'); distpath=Path(dist._path).resolve()
 assert sys.path[0]==str(base/'src') and origin.is_relative_to(base/'src') and distpath.is_relative_to(site) and distpath.name.endswith('.dist-info') and not list(base.rglob('*.egg-info'))
 assert not (tests/'__init__.py').exists()
 pkg=types.ModuleType('tests');pkg.__path__=[str(tests)];pkg.__package__='tests';pkg.__spec__=importlib.machinery.ModuleSpec('tests',loader=None,is_package=True);pkg.__spec__.submodule_search_locations=[str(tests)];sys.modules['tests']=pkg
 module=importlib.import_module('tests.test_wire_strategy_account_book'); assert Path(module.__file__).resolve().is_relative_to(tests)
 versions={}
 for name in ('pytest','pytest-asyncio','urllib3','msgpack'):
  try: versions[name]=importlib.metadata.version(name)
  except importlib.metadata.PackageNotFoundError: versions[name]=None
 emit('environment',python=sys.version,executable=sys.executable,versions=versions,sys_path_head=sys.path[:4],base_import=str(origin),dist_info=str(distpath),dist_version=dist.version,tests_namespace=module.__file__,test_tree_egg_info=[])
 args=['-p','no:cacheprovider','-p','pytest_asyncio.plugin','--basetemp','/private/tmp/iter65-full-retry.Dz1JCbxd/baseline-pytest','-q','tests']
 emit('configuration',args=args)
 class Recorder:
  def pytest_collection_finish(self,session): emit('collected',nodeids=[x.nodeid for x in session.items])
  def pytest_deselected(self,items): emit('deselected',nodeids=[x.nodeid for x in items])
  def pytest_collectreport(self,report):
   if report.failed or report.skipped: emit('collection_report',nodeid=report.nodeid,outcome=report.outcome,detail=str(report.longrepr))
  def pytest_runtest_logreport(self,report):
   item={'nodeid':report.nodeid,'phase':report.when,'outcome':report.outcome}
   if report.failed or report.skipped: item['detail']=str(report.longrepr)
   if hasattr(report,'wasxfail'): item['wasxfail']=str(report.wasxfail)
   emit('phase',**item)
  def pytest_warning_recorded(self,warning_message,when,nodeid,location): emit('warning',nodeid=nodeid,when=when,category=warning_message.category.__name__,message=str(warning_message.message),location=location)
 code=int(pytest.main(args,plugins=[Recorder()]));emit('exit',code=code)
except BaseException as e:
 emit('exception',type=type(e).__name__,detail=str(e)); raise
finally: stream.close()

